'use client'

import * as React from 'react'
import { cn } from "@/lib/utils"
import { cva, type VariantProps } from 'class-variance-authority'

import { Toggle, toggleVariants } from './toggle'

const ToggleGroupContext = React.createContext<{
  size?: VariantProps<typeof toggleVariants>['size']
  variant?: VariantProps<typeof toggleVariants>['variant']
  value: string[]
  onValueChange: (value: string, pressed: boolean) => void
  type: 'single' | 'multiple'
  disabled?: boolean
} | null>(null)

function useToggleGroup() {
  return React.useContext(ToggleGroupContext)
}

const ToggleGroup = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> &
    VariantProps<typeof toggleVariants> & {
      type: 'single' | 'multiple'
      value?: string | string[]
      defaultValue?: string | string[]
      onValueChange?: (value: any) => void
      disabled?: boolean
    }
>(
  (
    {
      className,
      variant,
      size,
      children,
      type,
      value,
      defaultValue,
      onValueChange,
      disabled,
      ...props
    },
    ref
  ) => {
    // Simple state management for group logic (Zag has toggleGroup but simple React state usually suffices for basic group)
    // We'll mimic Radix behavior.
    const [internalValue, setInternalValue] = React.useState<string[]>(() => {
      if (value !== undefined) return Array.isArray(value) ? value : value ? [value] : []
      if (defaultValue !== undefined)
        return Array.isArray(defaultValue) ? defaultValue : defaultValue ? [defaultValue] : []
      return []
    })

    const currentValue =
      value !== undefined ? (Array.isArray(value) ? value : value ? [value] : []) : internalValue

    const handleItemChange = (itemValue: string, pressed: boolean) => {
      let nextValue: string[] = []
      if (type === 'single') {
        nextValue = pressed ? [itemValue] : []
      } else {
        if (pressed) {
          nextValue = [...currentValue, itemValue]
        } else {
          nextValue = currentValue.filter((v) => v !== itemValue)
        }
      }

      if (value === undefined) {
        setInternalValue(nextValue)
      }

      if (onValueChange) {
        onValueChange(type === 'single' ? nextValue[0] || '' : nextValue)
      }
    }

    React.useEffect(() => {
      if (value !== undefined) {
        // Sync if needed, but derived state handles it
      }
    }, [value])

    return (
      <ToggleGroupContext.Provider
        value={{
          size,
          variant,
          value: currentValue,
          onValueChange: handleItemChange,
          type,
          disabled,
        }}
      >
        <div
          ref={ref}
          data-slot="toggle-group"
          role="group"
          className={cn('flex items-center justify-center gap-1', className)}
          {...props}
        >
          {children}
        </div>
      </ToggleGroupContext.Provider>
    )
  }
)
ToggleGroup.displayName = 'ToggleGroup'

const ToggleGroupItem = React.forwardRef<
  HTMLButtonElement,
  React.ComponentProps<typeof Toggle> & { value: string }
>(({ className, children, value, ...props }, ref) => {
  const context = useToggleGroup()
  const isSelected = context?.value.includes(value)
  const isDisabled = context?.disabled || props.disabled

  return (
    <Toggle
      ref={ref}
      data-slot="toggle-group-item"
      variant={context?.variant || props.variant}
      size={context?.size || props.size}
      pressed={isSelected}
      disabled={isDisabled}
      onPressedChange={(pressed: boolean) => {
        context?.onValueChange(value, pressed)
      }}
      className={cn(className)}
      {...props}
    >
      {children}
    </Toggle>
  )
})
ToggleGroupItem.displayName = 'ToggleGroupItem'

export { ToggleGroup, ToggleGroupItem }

import { setupToggleGroupMachine } from './use-toggle-group'

type WeappToggleGroupApi = {
  value?: string[]
  setValue?: (value: string[]) => void
}

type WeappService = {
  setContext: (context: Record<string, object>) => void
}

type ToggleGroupTapEvent = WechatMiniprogram.BaseEvent & {
  currentTarget: {
    dataset: {
      value?: string
    }
  }
}

type WeappToggleGroupInternal = WechatMiniprogram.Component.InstanceMethods<WechatMiniprogram.IAnyObject> & {
  _service?: WeappService
  _cleanup?: () => void
  _send?: (event: object) => void
  data: {
    api: WeappToggleGroupApi
  }
  properties: {
    value: string[]
    multiple: boolean
    disabled: boolean
    loop: boolean
    id: string
    extClass: string
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    value: { type: Array, value: [] },
    multiple: { type: Boolean, value: false },
    disabled: { type: Boolean, value: false },
    loop: { type: Boolean, value: true },
    id: { type: String, value: 'toggle-group' },
    extClass: { type: String, value: '' },
  },

  data: {
    api: {} as WeappToggleGroupApi,
    className: '',
  },

  lifetimes: {
    attached() {
      const self = this as WeappToggleGroupInternal
      const { service, cleanup, send } = setupToggleGroupMachine(this, {
        id: this.properties.id,
        value: this.properties.value,
        multiple: this.properties.multiple,
        disabled: this.properties.disabled,
        loop: this.properties.loop,
        onValueChange: (details) => {
          this.triggerEvent('change', details)
        }
      })

      self._service = service as WeappService
      self._cleanup = cleanup
      self._send = send as (event: object) => void
    },
    detached() {
      const self = this as WeappToggleGroupInternal
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as WeappToggleGroupInternal
      if (!state || !self._send) return
      const { connect } = setupToggleGroupMachine(this, { id: this.properties.id })
      const api = connect(state, self._send) as WeappToggleGroupApi
      this.setData({ api, className: this.properties.extClass })
    },

    'value': function (val) {
      const self = this as WeappToggleGroupInternal
      if (self._service) {
        self._service.setContext({ value: val })
      }
    },
  },

  methods: {
    onItemTap(e: ToggleGroupTapEvent) {
      const self = this as WeappToggleGroupInternal
      const value = e.currentTarget.dataset.value
      if (value && self.data.api.setValue) {
        const currentValue = self.data.api.value || []
        if (this.properties.multiple) {
          const newValue = currentValue.includes(value)
            ? currentValue.filter((v) => v !== value)
            : [...currentValue, value]
          self.data.api.setValue(newValue)
        } else {
          self.data.api.setValue([value])
        }
      }
    },
  },
})
